update public.learning_paths
set
  title = 'Special Topics Seminar',
  goal = 'Special Topics Seminar',
  summary = 'Students frame an advanced seminar through research questions, a defined corpus, and a clear scope; read primary texts, cultural objects, and Spanish-language scholarship with annotation, close reading, and synthesis; apply theoretical frameworks to evidence; situate materials in historical, regional, transatlantic, linguistic, and cultural contexts; locate and integrate scholarly and primary sources; lead discussion in Spanish; and develop a research argument from proposal and annotated bibliography through presentation, workshop, revision, and a final paper in academic Spanish.',
  data = $sptsjson${"slug": "special-topics-seminar", "title": "Special Topics Seminar", "description": "Students frame an advanced seminar through research questions, a defined corpus, and a clear scope; read primary texts, cultural objects, and Spanish-language scholarship with annotation, close reading, and synthesis; apply theoretical frameworks to evidence; situate materials in historical, regional, transatlantic, linguistic, and cultural contexts; locate and integrate scholarly and primary sources; lead discussion in Spanish; and develop a research argument from proposal and annotated bibliography through presentation, workshop, revision, and a final paper in academic Spanish.", "topics": [{"id": "182392bf-f66a-448e-af55-cce4bc0477cb", "type": "topic", "title": "1. Seminar Theme, Scope, and Research Questions", "description": "A special topics seminar must be focused enough to produce depth and flexible enough to support original student inquiry. This opening unit turns the broad theme into researchable questions, a shared vocabulary, and a workable corpus.", "children": [{"id": "b19c8aaa-01b8-4d6e-8050-6ba09b094539", "type": "subtopic", "title": "Theme definition and intellectual stakes", "children": [{"id": "46f34b22-a231-42cf-abda-83bf3470af07", "type": "concept", "title": "central problem or debate"}, {"id": "e65dc859-87ec-4155-a009-8977463a38f2", "type": "concept", "title": "key terms in Spanish"}, {"id": "aab43939-d0be-4a0f-9108-e6412245478d", "type": "concept", "title": "regional/period boundaries"}, {"id": "b5dcb50b-a035-45a0-998d-54e1640ed985", "type": "concept", "title": "disciplinary stakes"}], "description": "Students learn why the seminar topic matters and what scholarly conversations it enters."}, {"id": "eb3cf48f-bce0-4f5f-b8a4-bff80744803b", "type": "subtopic", "title": "Corpus and scope", "children": [{"id": "524ea9fa-e7e2-4343-b88a-62dbf21b229f", "type": "concept", "title": "authors or cultural objects"}, {"id": "46755709-380a-4945-acc5-e08ba64f2f91", "type": "concept", "title": "genres and media"}, {"id": "fe2572a1-14cf-42d8-a747-48abf4b0c571", "type": "concept", "title": "chronological limits"}, {"id": "f6f330bb-d30c-48b3-ab92-cd765bb0b93c", "type": "concept", "title": "inclusion/exclusion criteria"}], "description": "The point is to define what materials count as evidence and why they belong together."}, {"id": "97e9ab02-7091-45af-bcc5-636e860a6fa9", "type": "subtopic", "title": "Research-question design", "children": [{"id": "1ecf4bdf-7436-4d72-aedd-355cfc000f78", "type": "concept", "title": "open-ended questions"}, {"id": "1e9397ea-40eb-49a5-8d39-afc9392908d8", "type": "concept", "title": "why/how framing"}, {"id": "b918b986-5600-4120-b139-5263c78e916c", "type": "concept", "title": "feasibility"}, {"id": "869f4dde-0414-485a-ba14-0d4792eda24c", "type": "concept", "title": "revision of question over time"}], "description": "Students learn to move from broad curiosity to precise questions that can guide reading and writing."}]}, {"id": "fe2e34c4-9b0d-46c2-a7dd-ecf9ccd6b2d6", "type": "topic", "title": "2. Advanced Reading Strategies for Primary and Scholarly Texts", "description": "Advanced seminars require students to read slowly, strategically, and recursively. This section teaches reading as analysis: annotation, pattern recognition, close attention to form, and synthesis across texts.", "children": [{"id": "3ec2577f-f3e9-4c9c-b9e8-7c0f8cf589a7", "type": "subtopic", "title": "Close reading and formal analysis", "children": [{"id": "80640adc-4d59-4900-8046-1fa10da31e1b", "type": "concept", "title": "diction and syntax"}, {"id": "3d10c8b5-5e15-4fe5-90dc-d1f3345ec62d", "type": "concept", "title": "narrative voice"}, {"id": "3419b4bc-f977-44d0-93f9-846b169a0903", "type": "concept", "title": "genre conventions"}, {"id": "07dee5a1-296e-480b-add4-9dfa5cf48e10", "type": "concept", "title": "visual and filmic form"}], "description": "Students learn to treat language, form, genre, image, sound, and structure as evidence."}, {"id": "80b72239-ab19-4573-b6d3-73a6f68c5e8d", "type": "subtopic", "title": "Scholarly reading strategies", "children": [{"id": "fd748513-7b8c-488b-ad35-4faedcd28e82", "type": "concept", "title": "abstract and thesis"}, {"id": "88a82b89-4cf7-4858-b5ed-1f4f90f6c511", "type": "concept", "title": "method and corpus"}, {"id": "5f78f4fc-f96f-449d-8a8c-e5012884bbcc", "type": "concept", "title": "literature review"}, {"id": "60ceb96d-f03b-4567-b2a3-ab3edf130418", "type": "concept", "title": "claims vs evidence"}], "description": "The goal is to understand arguments, methods, and evidence without getting lost in every sentence."}, {"id": "8397899a-be11-4097-a1cd-8943a53408b8", "type": "subtopic", "title": "Annotation and reading logs", "children": [{"id": "c289291f-1d43-45d7-a373-41f6e6c571fc", "type": "concept", "title": "passage selection"}, {"id": "2b77e085-374c-4789-9d37-66371424f98d", "type": "concept", "title": "keywords"}, {"id": "a4441adc-f49d-499c-9445-39dcd78837fd", "type": "concept", "title": "questions for discussion"}, {"id": "244a6c50-1b12-44ee-8d27-123324ddba68", "type": "concept", "title": "source-to-source connections"}], "description": "Students build a reusable research record rather than isolated notes."}]}, {"id": "eb82bf71-9391-46a1-80d0-a777be6be1b4", "type": "topic", "title": "3. Theoretical Frameworks and Critical Methods", "description": "Theory should help students see evidence more clearly, not replace evidence. This unit introduces frameworks as tools for asking better questions and choosing appropriate methods.", "children": [{"id": "9bab7558-631c-4a0d-aec2-f098706e10a6", "type": "subtopic", "title": "Major critical lenses", "children": [{"id": "38f82f89-8d89-4a0d-9c10-5f7b9c9b0b01", "type": "concept", "title": "postcolonial and decolonial studies"}, {"id": "077450e7-f66f-4b44-9647-b9bfbc6b14da", "type": "concept", "title": "gender and sexuality studies"}, {"id": "bbac7988-8274-4a06-b21e-820279c2ae8b", "type": "concept", "title": "memory studies"}, {"id": "7c095776-461c-4a9a-b398-7ef779e97149", "type": "concept", "title": "race, ethnicity, and migration"}], "description": "Students encounter several approaches and learn what each makes visible."}, {"id": "41434e7f-bc4c-491f-8d02-bf46a2010048", "type": "subtopic", "title": "Method selection", "children": [{"id": "fe45be2a-392f-463f-860d-8e45d9a825f6", "type": "concept", "title": "close reading"}, {"id": "68dc1221-b3e8-4f45-aeba-ae692e4ec349", "type": "concept", "title": "cultural analysis"}, {"id": "05c83005-cd59-4e24-ba68-0989e36c2b5c", "type": "concept", "title": "film/media analysis"}, {"id": "f5681e0c-136a-4b96-8232-fcdc594e64f7", "type": "concept", "title": "historical contextualization"}], "description": "The point is to match method to corpus, question, and evidence."}, {"id": "77563777-d183-4e25-b08b-a93a23f8bc8e", "type": "subtopic", "title": "Responsible theory use", "children": [{"id": "6f097d14-b634-4128-8dce-79f34da3f481", "type": "concept", "title": "defining terms"}, {"id": "cbc3c889-d1cd-427c-885e-f2e57191eb21", "type": "concept", "title": "avoiding name-dropping"}, {"id": "67433de2-c621-4a95-9ccf-b6b4e7e35ce5", "type": "concept", "title": "limits of a framework"}, {"id": "8ccf02c2-407e-4484-8eeb-52f3387d9626", "type": "concept", "title": "theory-evidence alignment"}], "description": "Students learn to quote, explain, and apply theory without jargon-driven argument."}]}, {"id": "aaaeae55-9e6d-4a4c-8f50-7244cbad1891", "type": "topic", "title": "4. Historical, Regional, and Transatlantic Context", "description": "Texts and cultural objects emerge from specific histories and circulate across borders. Students learn to situate materials in context while avoiding simplistic background summaries.", "children": [{"id": "6c40b582-47ff-4737-a221-ab13be32c48f", "type": "subtopic", "title": "Historical framing", "children": [{"id": "28423fbb-a414-4275-88fc-c13f620c221f", "type": "concept", "title": "colonial histories"}, {"id": "b95e5b51-956b-45d5-a49c-3f8b1d97fadf", "type": "concept", "title": "dictatorship and democracy"}, {"id": "0493a2eb-f58d-4c67-991d-79f301d5bc03", "type": "concept", "title": "modernity and globalization"}, {"id": "b5446db4-d0fd-4bb6-9b0d-c70ed9f43a38", "type": "concept", "title": "social movements"}], "description": "Students identify events, institutions, conflicts, and social conditions that shape interpretation."}, {"id": "9c5212a2-009c-48cb-9d62-15abe4a86553", "type": "subtopic", "title": "Regional and linguistic variation", "children": [{"id": "72c6f15b-26a9-442b-9562-c574848c2191", "type": "concept", "title": "Iberian contexts"}, {"id": "3fc025fd-c48d-4297-86ad-4ec972842b06", "type": "concept", "title": "Latin American regions"}, {"id": "32110355-f1f1-4b57-ba96-e3110013158a", "type": "concept", "title": "U.S. Latinx contexts"}, {"id": "4d551fe6-b333-4572-ae26-20e878497f89", "type": "concept", "title": "language contact and dialect"}], "description": "The goal is to understand Spanish-speaking worlds as plural and internally diverse."}, {"id": "c0bfe824-8e19-487e-ab26-21d7e207a296", "type": "subtopic", "title": "Transatlantic and global flows", "children": [{"id": "5c4645f8-3a81-42f7-80a4-f3c28d36f64c", "type": "concept", "title": "migration and exile"}, {"id": "b34f069a-df2d-4b17-a502-2dca205d5d71", "type": "concept", "title": "translation and reception"}, {"id": "e8d12215-1fc3-48d4-a168-6ecc9409aa4e", "type": "concept", "title": "markets and publishing"}, {"id": "d5e984c4-f63f-4276-b5cb-4675d90c14a8", "type": "concept", "title": "comparative circulation"}], "description": "Students trace movement of texts, people, ideas, genres, and media."}]}, {"id": "4d72da44-7b61-46ca-bd38-ab054a43ca5d", "type": "topic", "title": "5. Primary Sources, Archives, and Digital Research", "description": "World-class seminars teach students how knowledge is made. This section introduces archival and digital research so students can move beyond secondary sources and build richer evidence bases.", "children": [{"id": "3f68461a-6f5a-43fb-958c-d5f7a7336039", "type": "subtopic", "title": "Primary-source identification", "children": [{"id": "243fa6b5-bf94-4f14-ba6c-adeb9c36f6a3", "type": "concept", "title": "literary texts"}, {"id": "909b5114-aa22-4192-a5ed-21d5cd900f0b", "type": "concept", "title": "periodicals and manifestos"}, {"id": "5b321bae-2c84-4a5b-94ac-8a83aa464d59", "type": "concept", "title": "film, image, and sound"}, {"id": "d5e1390a-177b-4f8b-aa65-a6d4f49a8dc4", "type": "concept", "title": "letters, interviews, oral histories"}], "description": "Students learn what counts as a primary source for different seminar themes."}, {"id": "a41011a2-0255-40af-b9eb-e3c69dd8163c", "type": "subtopic", "title": "Archives and digital libraries", "children": [{"id": "7793b6f6-cea3-41d7-aa91-0a3fd66df1e6", "type": "concept", "title": "catalog search"}, {"id": "629612d6-da98-4dd0-81c8-601d3a3e6b36", "type": "concept", "title": "metadata"}, {"id": "8ee9e7f8-73ef-4d81-9fe6-702413521079", "type": "concept", "title": "digitized collections"}, {"id": "84475820-e494-4fc2-a499-5bf8aaa82231", "type": "concept", "title": "permissions and access limits"}], "description": "The point is to locate materials, understand collection context, and document findings carefully."}, {"id": "01c8531a-188c-401f-89d7-8ea1c5003576", "type": "subtopic", "title": "Digital and corpus methods", "children": [{"id": "b15bfd58-4ea7-46eb-941a-bc2166a80cb1", "type": "concept", "title": "keyword searching"}, {"id": "0e824688-c000-4078-b797-d20a5877686e", "type": "concept", "title": "frequency and pattern noticing"}, {"id": "a5499df6-3741-44ae-a58d-ea2881d5db26", "type": "concept", "title": "mapping and timelines"}, {"id": "89f7a20e-ad1c-48da-af63-70128086fa0c", "type": "concept", "title": "limitations of digital evidence"}], "description": "Students gain light exposure to tools that can supplement close reading."}]}, {"id": "0c0ecd4f-602e-4136-b6e0-1efc770348b0", "type": "topic", "title": "6. Student-Led Discussion and Seminar Facilitation", "description": "Seminars work when students learn to lead inquiry, not merely report content. This unit develops discussion leadership in Spanish through interpretive questions, evidence, and inclusive facilitation.", "children": [{"id": "df1c8a07-fa20-499d-b9bb-7132feef0af3", "type": "subtopic", "title": "Question design", "children": [{"id": "0aca534f-e94e-4e55-b464-1d5704d236ac", "type": "concept", "title": "interpretive questions"}, {"id": "ca60c3d3-cb12-4e0a-9b95-b23ac86ce749", "type": "concept", "title": "comparative questions"}, {"id": "488b80f2-b5fd-448d-b147-e070ec4e0689", "type": "concept", "title": "method questions"}, {"id": "573f20a2-46b0-4cce-b112-7a69d807d601", "type": "concept", "title": "evidence-based follow-ups"}], "description": "Students learn to write questions that generate analysis rather than yes/no recall."}, {"id": "b1a34240-a013-4124-b8f8-f23ecbf3d4dd", "type": "subtopic", "title": "Facilitation moves", "children": [{"id": "c91c9cf1-c3ab-4972-beea-739eaf3e1733", "type": "concept", "title": "opening framing"}, {"id": "07d481ed-6310-4282-899b-a7261adc26ca", "type": "concept", "title": "redirecting to evidence"}, {"id": "f2ad4629-3c67-4fc2-b52a-f1ee2671d0a0", "type": "concept", "title": "synthesizing comments"}, {"id": "87b7722a-d14c-4da9-94ad-eec0cd2ec18b", "type": "concept", "title": "inviting quieter voices"}], "description": "The gist is to keep conversation rigorous, inclusive, and grounded in the text."}, {"id": "3f2332b2-20bd-4eec-af3a-6a04bef702e2", "type": "subtopic", "title": "Seminar Spanish and academic exchange", "children": [{"id": "3e0462e0-5d24-4cb3-9ae0-12e53c236e48", "type": "concept", "title": "Estoy de acuerdo porque..."}, {"id": "9ce54c14-fa92-4234-b786-8d5c1125d4f1", "type": "concept", "title": "Quisiera matizar..."}, {"id": "f2bd0646-c522-46a7-b868-afcf48696b40", "type": "concept", "title": "¿Podrías aclarar...?"}, {"id": "6bcd10da-a31f-43e8-a60a-8684dc4e8659", "type": "concept", "title": "Según el texto..."}], "description": "Students practice the language of disagreement, clarification, and scholarly contribution."}]}, {"id": "b0f8b78a-0450-4934-913f-4e64135bafc3", "type": "topic", "title": "7. Annotated Bibliography in Spanish and Source Evaluation", "description": "An annotated bibliography is a research map. Students learn to find sources, judge quality, summarize arguments in Spanish, and explain how each source changes the project.", "children": [{"id": "0c5ef947-8649-4501-a869-2b5d08004206", "type": "subtopic", "title": "Finding scholarly sources", "children": [{"id": "42e67794-3c57-4725-b8ca-3bb1d5ed01e6", "type": "concept", "title": "MLA International Bibliography"}, {"id": "5cac69a6-d810-4b2b-bc91-7eb90c790e02", "type": "concept", "title": "Dialnet"}, {"id": "d6cdf2ff-1bae-49b4-ae93-551a38270e4e", "type": "concept", "title": "library catalog"}, {"id": "49e085b1-b1de-4980-af56-e19136788d93", "type": "concept", "title": "journal databases"}], "description": "Students learn to search beyond the open web and use field-specific discovery tools."}, {"id": "054be7f5-802a-45b2-a40c-c9407b593bc6", "type": "subtopic", "title": "Evaluating relevance and credibility", "children": [{"id": "48025007-5041-4a85-ba09-19efe854c19b", "type": "concept", "title": "peer review"}, {"id": "9f283951-5d6e-4fa8-bfdd-0904cbd76cab", "type": "concept", "title": "publication venue"}, {"id": "27b47e73-4f6b-44f5-b90a-f2e936ecccc4", "type": "concept", "title": "methodological fit"}, {"id": "5fa760c1-bc36-40e4-809c-d79ca825d26e", "type": "concept", "title": "currency and field relevance"}], "description": "The point is to select sources for argument value, not just topic similarity."}, {"id": "a92c1666-cbcf-448c-b712-2220eb77bb70", "type": "subtopic", "title": "Writing annotations in Spanish", "children": [{"id": "a2eb3274-8aca-4902-b8e6-c1e89f14ab4c", "type": "concept", "title": "source thesis"}, {"id": "57ac2f12-7f59-4038-a70e-1694ca443cb0", "type": "concept", "title": "evidence and method"}, {"id": "f4c469ac-24d7-4357-90a7-fd64384a75a1", "type": "concept", "title": "usefulness to project"}, {"id": "386f3ae9-e8d0-42c2-a325-ab2eed1b8077", "type": "concept", "title": "keywords and tags"}], "description": "Students practice concise academic Spanish that summarizes, evaluates, and connects sources."}]}, {"id": "9348eada-c9bd-4ff7-86f4-95c87684066b", "type": "topic", "title": "8. Comparative, Interdisciplinary, and Ethical Interpretation", "description": "Special topics often cross borders, disciplines, and media. This section teaches comparison as a disciplined method and asks students to interpret ethically, especially across difference.", "children": [{"id": "f7164df0-9d58-4363-b6b2-bbedaa5e5c7f", "type": "subtopic", "title": "Comparative method", "children": [{"id": "b1543534-690c-4862-99a4-e105630a218c", "type": "concept", "title": "basis of comparison"}, {"id": "94a05877-4694-4e2c-b1a6-03ec0acfdbfd", "type": "concept", "title": "similarity and difference"}, {"id": "595f7d01-749d-445d-8829-d66c25c12468", "type": "concept", "title": "scale and asymmetry"}, {"id": "51a0f41b-e186-4703-813e-ee18645d4304", "type": "concept", "title": "limits of comparison"}], "description": "Students learn to compare without forcing false equivalence."}, {"id": "9f26ccd9-20b1-417d-8779-f0085569ec6b", "type": "subtopic", "title": "Interdisciplinary evidence", "children": [{"id": "a4eca24f-7716-412f-9a9b-135c62af3822", "type": "concept", "title": "disciplinary vocabulary"}, {"id": "31b30e7d-f308-4bd4-95d1-a42bf1dc2b61", "type": "concept", "title": "method transfer"}, {"id": "dab80342-bc37-424b-948d-ab21a5c03870", "type": "concept", "title": "mixed evidence"}, {"id": "f043c769-8fab-4429-96aa-083621826523", "type": "concept", "title": "argument coherence"}], "description": "The goal is to integrate history, art, film, linguistics, politics, or anthropology without losing focus."}, {"id": "adc6462d-5751-454d-bacc-50ad1a183949", "type": "subtopic", "title": "Ethical interpretation", "children": [{"id": "e9cef2eb-c897-40a1-bcaf-e9bfa4195bb3", "type": "concept", "title": "avoiding extraction"}, {"id": "6ab18857-2e02-46b8-a6ec-2aeb98538714", "type": "concept", "title": "citing marginalized voices"}, {"id": "b02223c2-16a7-4fe0-bb6a-5f5b160b5712", "type": "concept", "title": "translation choices"}, {"id": "fb838692-e3bd-4ed9-9414-53bae7104de7", "type": "concept", "title": "stereotype and overgeneralization checks"}], "description": "Students reflect on positionality, representation, translation, and citation ethics."}]}, {"id": "55ea82cc-4cd7-41ff-8ad3-86d17940a805", "type": "topic", "title": "9. Oral Research Presentation and Scholarly Exchange", "description": "The oral presentation trains students to communicate research publicly in Spanish. It emphasizes argument, evidence, pacing, visuals, and the ability to respond thoughtfully to questions.", "children": [{"id": "9c651943-81d1-4f81-a554-4addadaaa4d1", "type": "subtopic", "title": "Presentation architecture", "children": [{"id": "9beb3330-3086-4c76-a753-963b63ae6696", "type": "concept", "title": "title and research question"}, {"id": "a334b362-d11e-4092-a002-f256e7fd3b9e", "type": "concept", "title": "thesis"}, {"id": "c5fb266d-d019-421e-98b6-affc23b0ac40", "type": "concept", "title": "evidence sequence"}, {"id": "e68a0a3e-85e8-4e9a-bdc7-178d33f64aaf", "type": "concept", "title": "conclusion and stakes"}], "description": "Students learn to design a talk that has a clear claim and a manageable amount of evidence."}, {"id": "52ee1ad8-9b7c-4328-af91-9a9b6cec95a3", "type": "subtopic", "title": "Visual and oral delivery", "children": [{"id": "7caba02e-e737-41fc-a945-759a0a3c1526", "type": "concept", "title": "slide minimalism"}, {"id": "fbd364e8-5da0-4b8a-b68d-8718237a1cc3", "type": "concept", "title": "quotation display"}, {"id": "b6838e1e-6e08-4358-b8f3-b024ebab9f46", "type": "concept", "title": "image citation"}, {"id": "fc97d791-c310-4178-89e3-4bf7725fea32", "type": "concept", "title": "pace and pronunciation"}], "description": "The point is to support comprehension without overloading slides or reading from them."}, {"id": "46f2b2af-2f55-47fd-8e7b-44eb4d8a033f", "type": "subtopic", "title": "Q&A and scholarly dialogue", "children": [{"id": "92409585-7ff7-4d32-813c-391f52ee64c1", "type": "concept", "title": "clarification"}, {"id": "ed65c39b-4208-4c47-b7d3-a529da5ff265", "type": "concept", "title": "evidence-based response"}, {"id": "f9413432-47c4-48bb-a85f-331cae387907", "type": "concept", "title": "handling uncertainty"}, {"id": "eefd1199-6235-48d1-af4d-ae3b9039b053", "type": "concept", "title": "connecting to peer projects"}], "description": "Students practice answering questions, acknowledging limits, and extending discussion."}]}, {"id": "fc5bb87d-f2f1-4503-b153-f0da1d9b0b63", "type": "topic", "title": "10. Draft Workshop, Peer Review, and Argument Development", "description": "Drafting is where research becomes argument. This unit gives students protocols for peer review that address thesis, structure, evidence, counterargument, and contribution.", "children": [{"id": "622f93f8-7ed8-47d7-83d8-3829e8446e5a", "type": "subtopic", "title": "Thesis and argument map", "children": [{"id": "faef033c-63d9-43f8-9fbc-48094a92411c", "type": "concept", "title": "working thesis"}, {"id": "48118bf2-fcf2-4455-a0e1-13635035e374", "type": "concept", "title": "stakes"}, {"id": "769ba909-79e1-4649-a48e-343f44c52f88", "type": "concept", "title": "section sequence"}, {"id": "ddf52a23-56db-4fe1-864a-bccd2c3ca0a4", "type": "concept", "title": "claim hierarchy"}], "description": "Students learn to check whether the paper has a debatable claim and logical progression."}, {"id": "0ee2f50f-55ec-4c21-b333-e91b684bb7c5", "type": "subtopic", "title": "Evidence and paragraph logic", "children": [{"id": "1d746d53-0e14-498a-a5d1-974b64c8fb08", "type": "concept", "title": "topic sentences"}, {"id": "624039fd-b6d6-460b-8556-cf6bfe6b6874", "type": "concept", "title": "quotation integration"}, {"id": "1f70487b-b076-489c-85b5-35057920f2b3", "type": "concept", "title": "close analysis"}, {"id": "75b37443-326f-403c-97f9-53ed2e9edebe", "type": "concept", "title": "source synthesis"}], "description": "The goal is to make each paragraph do analytical work rather than summarize."}, {"id": "0e064822-079f-4c63-9954-646b951d42cc", "type": "subtopic", "title": "Peer review protocol", "children": [{"id": "91906868-6108-499c-b928-328a2c907358", "type": "concept", "title": "reader questions"}, {"id": "bbe6ca53-98cc-4e4b-a802-b9134c964f1d", "type": "concept", "title": "global comments"}, {"id": "fa22e2d5-1467-4c4f-8979-31e9aa54ef8b", "type": "concept", "title": "local style notes"}, {"id": "c8e74aa2-8993-4de8-83f0-192f51cc5919", "type": "concept", "title": "revision priorities"}], "description": "Students practice giving useful feedback in Spanish and receiving critique without defensiveness."}]}, {"id": "5283e108-7436-42cb-a886-c8787aebfe4c", "type": "topic", "title": "11. Revision in Spanish: Style, Register, and Citation Practice", "description": "Advanced Spanish writing requires revision at the level of argument, paragraph, sentence, and citation. This unit develops academic register and clean source integration.", "children": [{"id": "9970db63-5561-4244-be36-dc29826e94a3", "type": "subtopic", "title": "Academic Spanish style", "children": [{"id": "909d1105-4cc2-47f7-824a-37861dbb1016", "type": "concept", "title": "nominalization with care"}, {"id": "2e7f587a-f596-4b83-89f9-b7733d907a29", "type": "concept", "title": "connectors"}, {"id": "03033d5e-429d-4943-aa78-54fa7cae0df8", "type": "concept", "title": "avoiding English calques"}, {"id": "9c80f28b-d203-4e4e-b0c0-f3a913e8d259", "type": "concept", "title": "disciplinary vocabulary"}], "description": "Students refine clarity, precision, transitions, and tone."}, {"id": "69079adf-0bf3-43c6-b915-3e92b0cc07eb", "type": "subtopic", "title": "Grammar and syntax revision", "children": [{"id": "0f4932b9-cf1a-42b5-8858-942f0f428cc4", "type": "concept", "title": "subjunctive in argument"}, {"id": "030af106-89e6-460d-b886-88e6d5060852", "type": "concept", "title": "relative clauses"}, {"id": "307ed814-d997-446d-a199-5a8cc24f2a79", "type": "concept", "title": "prepositions"}, {"id": "68d80284-2ea2-48b6-a6fc-4e3b4cc45b30", "type": "concept", "title": "agreement and accent marks"}], "description": "The point is to polish recurring advanced errors that distract from argument."}, {"id": "028f5f01-5a17-4e3b-8ab8-ffb2fe9a5d67", "type": "subtopic", "title": "Citation and source integration", "children": [{"id": "1fb5c4b2-c54c-440c-aaaf-272c41e9171a", "type": "concept", "title": "MLA in-text citation"}, {"id": "904a5f7a-a1dd-4c52-9469-cee4dc0674ed", "type": "concept", "title": "works cited"}, {"id": "b4684ea1-fc02-4761-995d-8c023abd929d", "type": "concept", "title": "signal phrases"}, {"id": "8d431eb8-4eed-45a1-a30b-e3448bf2620b", "type": "concept", "title": "quotation/paraphrase balance"}], "description": "Students learn to document responsibly and make sources converse with their own claims."}]}, {"id": "c2d9dee4-88f6-4f64-a8ce-77b8329b8794", "type": "topic", "title": "12. Final Seminar Paper and Research Portfolio", "description": "The final product should show both a polished argument and the process that made it possible. The portfolio documents inquiry, sources, presentation, feedback, and revision.", "children": [{"id": "bb868bb6-7844-424e-8d53-d28589bc7947", "type": "subtopic", "title": "Final paper components", "children": [{"id": "260608ac-49fc-466b-928a-71cf858c1707", "type": "concept", "title": "introduction and thesis"}, {"id": "743991ec-3bd6-4cd3-9485-83c79ad5112e", "type": "concept", "title": "context and method"}, {"id": "693d89d1-a8c4-4988-837a-f54ff292dedd", "type": "concept", "title": "analytical sections"}, {"id": "33fb7d75-0ed1-4b7f-94ee-e1a74d1a158b", "type": "concept", "title": "conclusion and stakes"}], "description": "Students assemble a coherent advanced research paper in Spanish."}, {"id": "a9000c4b-8b46-4131-b959-5da6f92e8bda", "type": "subtopic", "title": "Research portfolio", "children": [{"id": "693fa26a-80bd-43b2-be42-3560fe0c915a", "type": "concept", "title": "proposal"}, {"id": "499b019c-2d31-4489-9a93-8262af6eeec6", "type": "concept", "title": "annotated bibliography"}, {"id": "edbcf3ca-12fc-4b47-8a49-0ef3644c8261", "type": "concept", "title": "draft and feedback"}, {"id": "ac30d01d-4db1-4068-b3bc-cb1c808f4199", "type": "concept", "title": "presentation materials"}], "description": "The portfolio makes research labor visible and prepares students for capstone or graduate-level work."}, {"id": "b28e5f8d-2800-444e-8abc-f7f05c22e710", "type": "subtopic", "title": "Reflection and transfer", "children": [{"id": "9891eef1-8d5d-427e-8335-67e69e22bdde", "type": "concept", "title": "research growth"}, {"id": "e6058dc1-3f6c-488a-8bc9-f29017b219f2", "type": "concept", "title": "Spanish writing growth"}, {"id": "4cd0f5fd-2aca-4edb-b3da-e0a1f1db7773", "type": "concept", "title": "future questions"}, {"id": "b39a0474-4fdf-480b-8e1d-897239ea21e0", "type": "concept", "title": "capstone/graduate readiness"}], "description": "Students articulate what they learned and how they will carry methods forward."}]}], "dbBacked": true}$sptsjson$::jsonb,
