values
  ('182392bf-f66a-448e-af55-cce4bc0477cb', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', null, 'topic'::public.curated_course_node_type, '1. Seminar Theme, Scope, and Research Questions', 'A special topics seminar must be focused enough to produce depth and flexible enough to support original student inquiry. This opening unit turns the broad theme into researchable questions, a shared vocabulary, and a workable corpus.', 0),
  ('b19c8aaa-01b8-4d6e-8050-6ba09b094539', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', '182392bf-f66a-448e-af55-cce4bc0477cb', 'subtopic'::public.curated_course_node_type, 'Theme definition and intellectual stakes', 'Students learn why the seminar topic matters and what scholarly conversations it enters.', 0),
  ('46f34b22-a231-42cf-abda-83bf3470af07', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', 'b19c8aaa-01b8-4d6e-8050-6ba09b094539', 'concept'::public.curated_course_node_type, 'central problem or debate', null, 0),
