  ('869f4dde-0414-485a-ba14-0d4792eda24c', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', '97e9ab02-7091-45af-bcc5-636e860a6fa9', 'concept'::public.curated_course_node_type, 'revision of question over time', null, 3),
  ('fe2e34c4-9b0d-46c2-a7dd-ecf9ccd6b2d6', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', null, 'topic'::public.curated_course_node_type, '2. Advanced Reading Strategies for Primary and Scholarly Texts', 'Advanced seminars require students to read slowly, strategically, and recursively. This section teaches reading as analysis: annotation, pattern recognition, close attention to form, and synthesis across texts.', 1),
  ('3ec2577f-f3e9-4c9c-b9e8-7c0f8cf589a7', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', 'fe2e34c4-9b0d-46c2-a7dd-ecf9ccd6b2d6', 'subtopic'::public.curated_course_node_type, 'Close reading and formal analysis', 'Students learn to treat language, form, genre, image, sound, and structure as evidence.', 0),
  ('80640adc-4d59-4900-8046-1fa10da31e1b', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', '3ec2577f-f3e9-4c9c-b9e8-7c0f8cf589a7', 'concept'::public.curated_course_node_type, 'diction and syntax', null, 0),
