  ('80b72239-ab19-4573-b6d3-73a6f68c5e8d', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', 'fe2e34c4-9b0d-46c2-a7dd-ecf9ccd6b2d6', 'subtopic'::public.curated_course_node_type, 'Scholarly reading strategies', 'The goal is to understand arguments, methods, and evidence without getting lost in every sentence.', 1),
