  ('244a6c50-1b12-44ee-8d27-123324ddba68', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', '8397899a-be11-4097-a1cd-8943a53408b8', 'concept'::public.curated_course_node_type, 'source-to-source connections', null, 3),
