  ('aaaeae55-9e6d-4a4c-8f50-7244cbad1891', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', null, 'topic'::public.curated_course_node_type, '4. Historical, Regional, and Transatlantic Context', 'Texts and cultural objects emerge from specific histories and circulate across borders. Students learn to situate materials in context while avoiding simplistic background summaries.', 3),
