insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('0c0ecd4f-602e-4136-b6e0-1efc770348b0', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', null, 'topic'::public.curated_course_node_type, '6. Student-Led Discussion and Seminar Facilitation', 'Seminars work when students learn to lead inquiry, not merely report content. This unit develops discussion leadership in Spanish through interpretive questions, evidence, and inclusive facilitation.', 5),
  ('df1c8a07-fa20-499d-b9bb-7132feef0af3', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', '0c0ecd4f-602e-4136-b6e0-1efc770348b0', 'subtopic'::public.curated_course_node_type, 'Question design', 'Students learn to write questions that generate analysis rather than yes/no recall.', 0),
