  ('3e0462e0-5d24-4cb3-9ae0-12e53c236e48', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', '3f2332b2-20bd-4eec-af3a-6a04bef702e2', 'concept'::public.curated_course_node_type, 'Estoy de acuerdo porque...', null, 0),
