  ('6bcd10da-a31f-43e8-a60a-8684dc4e8659', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', '3f2332b2-20bd-4eec-af3a-6a04bef702e2', 'concept'::public.curated_course_node_type, 'Según el texto...', null, 3),
  ('b0f8b78a-0450-4934-913f-4e64135bafc3', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', null, 'topic'::public.curated_course_node_type, '7. Annotated Bibliography in Spanish and Source Evaluation', 'An annotated bibliography is a research map. Students learn to find sources, judge quality, summarize arguments in Spanish, and explain how each source changes the project.', 6),
