  ('054be7f5-802a-45b2-a40c-c9407b593bc6', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', 'b0f8b78a-0450-4934-913f-4e64135bafc3', 'subtopic'::public.curated_course_node_type, 'Evaluating relevance and credibility', 'The point is to select sources for argument value, not just topic similarity.', 1),
  ('48025007-5041-4a85-ba09-19efe854c19b', 'a7b8c9d0-1e2f-4a72-9b22-3c4d5e6f7a02', '054be7f5-802a-45b2-a40c-c9407b593bc6', 'concept'::public.curated_course_node_type, 'peer review', null, 0),
